<?php
namespace App\Http\Controllers;
use App\Models\{User,Location,Building,Floor,Room,Report,ReportUpdate,Attachment};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash,Storage};
use Illuminate\Validation\Rule;
use Illuminate\Support\Str;
class SirumahController extends Controller {
 private array $categories=['Air tidak mengalir','Air berwarna kuning / berbau','Lampu mati','AC rusak','Toilet tersumbat','Pintu / kunci rusak','Kebersihan kamar mandi','Kerusakan tempat tidur','Gangguan listrik','Lainnya'];
 public function home(){return Auth::check()?redirect()->route('dashboard'):view('welcome');}
 public function loginForm(){return view('auth', ['register'=>false]);}
 public function registerForm(){return view('auth',['register'=>true]);}
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt(['email'=>$v['email'],'password'=>$v['password'],'is_active'=>true]))return back()->withErrors(['email'=>'Email atau kata sandi salah, atau akun dinonaktifkan.'])->onlyInput('email');$r->session()->regenerate();return redirect()->intended(route('dashboard'));}
 public function register(Request $r){$v=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:255|unique:users,email','student_number'=>'required|string|max:50','department'=>['required',Rule::in(['Teknologi Laboratorium Medis','Keperawatan','Kebidanan'])],'password'=>'required|string|min:12|confirmed']);$v['role']='student';$v['is_active']=true;$user=User::create($v);Auth::login($user);$r->session()->regenerate();return redirect()->route('dashboard');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');}
 public function buildings(Location $location){return response()->json($location->buildings()->where('active',true)->orderBy('name')->get(['id','name']));}
 public function floors(Building $building){return response()->json($building->floors()->where('active',true)->orderBy('name')->get(['id','name']));}
 public function rooms(Floor $floor){return response()->json($floor->rooms()->where('active',true)->orderBy('name')->get(['id','name']));}
 private function scoped(){ $u=Auth::user(); if(in_array($u->role,['superadmin','verifier'],true))return Report::query(); if($u->role==='admin')return Report::whereHas('user',fn($q)=>$q->where('department',$u->department)); return Report::where('user_id',$u->id); }
 public function dashboard(){ $query=$this->scoped(); $total=(clone $query)->count();$counts=[];foreach(['received','handling','scheduled','completed'] as $s)$counts[$s]=(clone $query)->where('status',$s)->count();$reports=$query->with(['location','room','user'])->latest()->limit(6)->get();return view('dashboard',compact('total','counts','reports'));}
 public function create(){return view('create',['locations'=>Location::where('active',true)->orderBy('name')->get(),'categories'=>$this->categories]);}
 public function store(Request $r){$v=$r->validate(['location_id'=>'required|exists:locations,id','building_id'=>'required|exists:buildings,id','floor_id'=>'required|exists:floors,id','room_id'=>'required|exists:rooms,id','category'=>['required',Rule::in($this->categories)],'title'=>'required|string|max:140','description'=>'required|string|min:15|max:5000','evidence'=>'required|array|min:1|max:5','evidence.*'=>'required|file|mimes:jpg,jpeg,png,webp,mp4,mov,webm|max:20480']);
 $location=Location::findOrFail($v['location_id']);$building=Building::findOrFail($v['building_id']);$floor=Floor::findOrFail($v['floor_id']);$room=Room::findOrFail($v['room_id']);abort_unless($location->active && $building->active && $floor->active && $room->active && $building->location_id==$location->id && $floor->building_id==$building->id && $room->floor_id==$floor->id,422,'Lokasi tidak sesuai.');
 $report=DB::transaction(function()use($r,$v){$report=Report::create(['ticket'=>'KB'.now()->format('Ymd').strtoupper(Str::random(7)),'user_id'=>Auth::id(),'location_id'=>$v['location_id'],'building_id'=>$v['building_id'],'floor_id'=>$v['floor_id'],'room_id'=>$v['room_id'],'category'=>$v['category'],'title'=>$v['title'],'description'=>$v['description'],'status'=>'received']);ReportUpdate::create(['report_id'=>$report->id,'user_id'=>Auth::id(),'status'=>'received','note'=>'Laporan Anda diterima.']);foreach($r->file('evidence') as $file){$path=$file->store('sirumah/'.$report->id,'local');Attachment::create(['report_id'=>$report->id,'path'=>$path,'mime'=>$file->getMimeType(),'original_name'=>$file->getClientOriginalName(),'size'=>$file->getSize()]);}return $report;});return redirect()->route('reports.show',$report)->with('success','Pengaduan berhasil dikirim.');}
 public function index(Request $r){$query=$this->scoped()->with(['location','user']);if($r->filled('status')&&in_array($r->status,['received','handling','scheduled','completed']))$query->where('status',$r->status);if($r->filled('q')){$q=substr($r->q,0,100);$query->where(function($builder)use($q){$builder->where('ticket','like','%'.$q.'%')->orWhere('title','like','%'.$q.'%');});}return view('index',['reports'=>$query->latest()->paginate(15)->withQueryString()]);}
 private function authorizeReport(Report $report):void{abort_unless((Auth::user()->role==='admin' && $report->user->department===Auth::user()->department) || in_array(Auth::user()->role,['superadmin','verifier'],true) || $report->user_id===Auth::id(),403);}
 public function show(Report $report){$this->authorizeReport($report);$report->load(['location','building','floor','room','user','updates.user','attachments']);return view('show',compact('report'));}
 public function media(Report $report,Attachment $media){$this->authorizeReport($report);abort_unless($media->report_id===$report->id,404);abort_unless(Storage::disk('local')->exists($media->path),404);return response()->file(Storage::disk('local')->path($media->path),['Content-Type'=>$media->mime,'X-Content-Type-Options'=>'nosniff','Content-Disposition'=>'inline; filename="evidence"','Cache-Control'=>'private, no-store']);}
 public function updateStatus(Request $r,Report $report){abort_unless(Auth::user()->isStaff(),403);$this->authorizeReport($report);$v=$r->validate(['status'=>['required',Rule::in(['received','handling','scheduled','completed'])],'note'=>'nullable|string|max:2000','planned_date'=>'required_if:status,scheduled|nullable|date|after_or_equal:today']);$report->update(['status'=>$v['status'],'planned_date'=>$v['status']==='scheduled'?$v['planned_date']:null,'assigned_to'=>Auth::id()]);ReportUpdate::create(['report_id'=>$report->id,'user_id'=>Auth::id(),'status'=>$v['status'],'note'=>$v['note']??null,'planned_date'=>$v['status']==='scheduled'?$v['planned_date']:null]);return back()->with('success','Status diperbarui. Riwayat dan notifikasi pelapor telah diperbarui.');}
 public function notifications(){ $reports=$this->scoped()->with(['updates'=>function($q){$q->latest();}])->latest()->limit(50)->get();$items=$reports->flatMap(fn($report)=>$report->updates->map(fn($u)=>(object)['ticket'=>$report->ticket,'report_id'=>$report->id,'status'=>$u->status,'note'=>$u->note,'planned_date'=>$u->planned_date,'created_at'=>$u->created_at]))->sortByDesc('created_at')->take(50);return view('notifications',compact('items'));}
 public function settings(){abort_unless(Auth::user()->isSuper(),403);$locations=Location::with('buildings.floors.rooms')->get();$masters=['location'=>$locations->map(fn($l)=>['id'=>$l->id,'name'=>$l->name])->values(),'building'=>$locations->flatMap(fn($l)=>$l->buildings->map(fn($b)=>['id'=>$b->id,'name'=>$l->name.' / '.$b->name]))->values(),'floor'=>$locations->flatMap(fn($l)=>$l->buildings->flatMap(fn($b)=>$b->floors->map(fn($f)=>['id'=>$f->id,'name'=>$l->name.' / '.$b->name.' / '.$f->name])))->values()];return view('settings',['locations'=>$locations,'masters'=>$masters,'users'=>User::where('role','!=','student')->orderBy('role')->get()]);}
 public function saveMaster(Request $r){abort_unless(Auth::user()->isSuper(),403);$v=$r->validate(['type'=>['required',Rule::in(['location','building','floor','room'])],'parent_id'=>'nullable|integer','name'=>'required|string|max:80']);$models=['location'=>Location::class,'building'=>Building::class,'floor'=>Floor::class,'room'=>Room::class];$relations=['building'=>['location_id',Location::class],'floor'=>['building_id',Building::class],'room'=>['floor_id',Floor::class]];$data=['name'=>trim($v['name']),'active'=>true];if($v['type']!=='location'){$parent=$relations[$v['type']];$parent[1]::findOrFail($v['parent_id']??0);$data[$parent[0]]=$v['parent_id'];}$models[$v['type']]::firstOrCreate($data);return back()->with('success','Master lokasi berhasil disimpan.');}
 public function saveUser(Request $r){abort_unless(Auth::user()->isSuper(),403);$v=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|unique:users,email','password'=>'required|string|min:12','role'=>['required',Rule::in(['admin','verifier'])],'department'=>['nullable',Rule::in(['Teknologi Laboratorium Medis','Keperawatan','Kebidanan'])]]);if($v['role']==='admin'&&!isset($v['department']))return back()->withErrors(['department'=>'Jurusan wajib dipilih untuk admin jurusan.']);User::create($v+['is_active'=>true]);return back()->with('success','Akun petugas telah dibuat.');}
 public function toggleUser(User $user){abort_unless(Auth::user()->isSuper(),403);abort_if($user->id===Auth::id() || $user->role==='superadmin',403);$user->update(['is_active'=>!$user->is_active]);return back()->with('success','Status akun diubah.');}
}
